const listUserBadgesByUsername = `-- name: ListUserBadgesByUsername :many
SELECT
 ub.id, ub.user_id, ub.badge_id, ub.awarded_at, ub.awarded_by,
 bd.name AS badge_name,
 bd.slug AS badge_slug,
 bd.description AS badge_description,
 bd.accent_color AS badge_accent_color,
 bd.icon_media_id AS badge_icon_media_id,
 bd.category AS badge_category,
 bd.rarity AS badge_rarity,
 bd.tier AS badge_tier,
 bd.badge_group AS badge_group
FROM user_badges ub
JOIN badge_definitions bd ON bd.id = ub.badge_id
JOIN users u ON u.id = ub.user_id
WHERE (u.username = $1 OR lower(u.public_username) = lower($1)
 -- §50 former-username amendment: resolves a former handle to the owner's
 -- current canonical; inert while any live handle claims the name.
 OR u.username = (SELECT u2.username FROM username_redirects ur
                  JOIN users u2 ON u2.id = ur.user_id AND u2.status != 'deleted'
                 WHERE ur.username = $1
                   AND NOT EXISTS (SELECT 1 FROM users ux
                                    WHERE ux.username = $1
                                       OR lower(ux.public_username) = lower($1))))
ORDER BY ub.awarded_at DESC
`

